/* =====================================================================
   LYRA KNOWLEDGE — pre-written glossary + explainers (offline, no AI)
   ---------------------------------------------------------------------
   Loaded before assistant.js. Exposes window.LyraKnowledge:
     explainField(def, ctx)  -> structured explanation for ANY form field
     explainDoc(cfg)         -> "what is this document" from its own config
     search(query)           -> glossary + documents + fields matching a question
     suggestFix(value, def)  -> format-only correction that satisfies the field's pattern
     exampleFor(def)         -> a sample value / format for the field
   Explanation order for a field: the field's own `learn` block -> glossary
   (matched on the label / field name) -> its `help` text -> a generic line
   that names the document and step. Nothing is generated at runtime; every
   sentence below was written by hand.
   ===================================================================== */
(function(){
  "use strict";

  /* ---------- text helpers ---------- */
  const stem = w => (w.length > 3 && /s$/.test(w) && !/ss$/.test(w)) ? w.slice(0, -1) : w;
  const norm = s => String(s == null ? "" : s)
    .replace(/([a-z])([A-Z])/g, "$1 $2")            // camelCase -> words
    .toLowerCase().replace(/[^a-z0-9]+/g, " ").trim().split(/\s+/).filter(Boolean).map(stem);
  const hasSeq = (tokens, seq) => {
    if(!seq.length) return false;
    for(let i = 0; i + seq.length <= tokens.length; i++){ let ok = true; for(let j = 0; j < seq.length; j++){ if(tokens[i + j] !== seq[j]){ ok = false; break; } } if(ok) return true; }
    return false;
  };
  const esc = x => String(x == null ? "" : x).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;");
  const stripTags = s => String(s == null ? "" : s).replace(/<[^>]*>/g, " ").replace(/&nbsp;/g, " ").replace(/\s+/g, " ").trim();

  /* ---------- the glossary ---------- */
  const GLOSSARY = [];
  /* add(title, "alias|alias|...", definition, example, why/where) */
  function add(t, k, d, x, w){ GLOSSARY.push({t, k: k.split("|").map(s => s.trim()).filter(Boolean), d, x: x || "", w: w || "", tk: norm(t), kt: k.split("|").map(s => norm(s)).filter(a => a.length) }); }

  /* ===== PARTIES ===== */
  add("Shipper / Consignor / Exporter","shipper|consignor|exporter|seller|supplier|consignor name","The party that sends the goods and hands them to the carrier. On export documents the shipper is normally the exporter (the Indian seller named on the invoice and Shipping Bill).","Meenachil Agro Exports Pvt Ltd, Kochi","The shipper\u2019s name must read the same on the invoice, Shipping Bill and Bill of Lading \u2014 the bank and Customs match them.");
  add("Consignee","consignee|consignee name|ship to","The party the goods are being sent to \u2014 the one named on the Bill of Lading as the receiver. It is usually the buyer, but it can also be the buyer\u2019s bank (\u201cto order of\u201d) when payment is by Letter of Credit.","Gulf Pearl Foodstuff Trading LLC, Dubai","The consignee decides who can take delivery. A wrong consignee means the cargo cannot be released to the real buyer.");
  add("Notify Party","notify party|notify|also notify|second notify","The person or company the carrier informs when the cargo arrives (for example the buyer\u2019s clearing agent). The notify party does not own the goods and cannot take delivery just because they are notified.","Jebel Ali Clearing & Forwarding LLC","Notify details let the destination agent start customs clearance before the importer collects the documents.");
  add("Importer / Buyer","importer|buyer|importer name|purchaser|bill to|customer|applicant","The party in the destination country that buys the goods and pays for them. The importer files the Bill of Entry (in India) and pays the import duty.","Gulf Pearl Foodstuff Trading LLC","The buyer\u2019s legal name and address should be identical on every document of the shipment.");
  add("Applicant (Letter of Credit)","applicant|lc applicant|opening applicant","In a Letter of Credit, the buyer who asks their bank to open the credit in favour of the seller.","","The applicant\u2019s name must match the buyer on the invoice, or the bank will list a discrepancy.");
  add("Beneficiary","beneficiary|lc beneficiary","The party who will be paid under a Letter of Credit or Bank Guarantee \u2014 in an export LC that is the seller/exporter.","","The beneficiary name on the documents must match the LC exactly.");
  add("Issuing Bank","issuing bank|opening bank|issuer bank","The buyer\u2019s bank that issues (opens) the Letter of Credit and promises to pay if the seller presents compliant documents.","","");
  add("Advising Bank","advising bank|advise through|advising","The bank in the seller\u2019s country that passes the Letter of Credit to the seller after checking it is genuine. It does not add its own payment promise unless it also confirms.","","");
  add("Confirming Bank","confirming bank|confirmation|confirmed lc|confirm","A bank that adds its own guarantee of payment to the Letter of Credit, so the seller is protected even if the issuing bank fails to pay.","","");
  add("Negotiating Bank","negotiating bank|negotiation|nominated bank","The bank that checks the seller\u2019s documents against the LC and pays or buys them, then claims reimbursement from the issuing bank.","","");
  add("Drawer / Drawee / Payee","drawer|drawee|payee","In a Bill of Exchange: the drawer writes (signs) the bill \u2014 the exporter; the drawee is who must pay it \u2014 the buyer or buyer\u2019s bank; the payee is who receives the money \u2014 usually the exporter or their bank.","","");
  add("Carrier / Shipping Line","carrier|shipping line|steamship line|airline|carrier name|carrier agent|line","The company that actually moves the cargo \u2014 a shipping line for sea freight, an airline for air freight. The carrier issues the Bill of Lading or Air Waybill.","Maersk Line, MSC, Air India Cargo","");
  add("Freight Forwarder","freight forwarder|forwarder|nvocc|forwarding agent|forwarder s","A company that arranges transport for the shipper \u2014 books space with carriers, prepares documents and tracks the cargo. A forwarder that issues its own House Bill of Lading without owning ships is called an NVOCC.","","");
  add("Customs House Agent (CHA) / Customs Broker","cha|customs house agent|customs broker|cha license|cha licence|cha name|broker","A licensed professional who files Customs documents (Shipping Bill, Bill of Entry) on behalf of the exporter or importer through ICEGATE.","CHA licence e.g. 11/1234","Customs only accepts filings from the importer/exporter or their licensed CHA.");
  add("Authorized Signatory","authorized signatory|authorised signatory|signatory|signatory name|signed by|signature|authorized person","The person who is legally allowed to sign this document for the company. Their name and designation must be someone with that authority (director, partner, authorised manager).","Rahul Menon, Director","");
  add("Designation","designation|job title|position|role","The signatory\u2019s job title in the company, for example Director, Export Manager or Authorised Signatory.","Export Manager","");
  add("Customs / CBIC","customs|cbic|customs authority|customs office|customs department","The Government of India authority (Central Board of Indirect Taxes and Customs) that controls cargo entering or leaving India and collects customs duty.","","");
  add("DGFT","dgft|directorate general of foreign trade","The Directorate General of Foreign Trade \u2014 the authority that issues the Importer-Exporter Code (IEC), export/import licences and runs India\u2019s foreign-trade schemes.","","");
  add("RBI / AD Bank","rbi|reserve bank|ad bank|authorised dealer|authorized dealer|ad code","The Reserve Bank of India regulates foreign-exchange rules. An Authorised Dealer (AD) bank is the bank allowed to handle your export proceeds; its AD code is registered with Customs for export shipments.","","");
  add("Port Trust / Terminal Operator","port trust|terminal operator|terminal|port authority|berth operator","The body that runs the port or the container terminal where cargo is received, stacked and loaded or unloaded.","","");
  add("CFS / ICD / CY","cfs|icd|cy|container freight station|inland container depot|container yard|container depot","Places where containers are handled away from the ship: a CFS stuffs/destuffs LCL cargo, an ICD is an inland port with Customs, a CY (container yard) stores full containers near the vessel.","","");
  add("Transporter / Haulier","transporter|haulier|trucker|transport company|logistics provider|lsp|3pl","The trucking or logistics company that moves the cargo by road between factory, warehouse, port or customer.","","");

  /* ===== IDENTIFIERS & CODES ===== */
  add("IEC \u2014 Importer Exporter Code","iec|importer exporter code|iec number|iec code","A 10-digit code issued by DGFT to every business that imports or exports from India. Without an IEC Customs will not accept your Shipping Bill or Bill of Entry.","0123456789 (10 digits)","It identifies the exporter in Customs, the bank and DGFT schemes. The same IEC must appear on the invoice, Shipping Bill and BRC.");
  add("GSTIN","gstin|gst number|gst no|gst identification number|gst registration|tax registration|gst reg","The 15-character GST Identification Number. The first 2 digits are the state code, the next 10 are the business\u2019s PAN, then an entity number, the letter Z, and a check character.","32AAAAA0000A1Z5","Tax invoices and e-way bills must show the correct GSTIN of supplier and (for domestic sales) buyer.");
  add("PAN","pan|permanent account number|pan number|pan no","Permanent Account Number \u2014 the 10-character income-tax ID of a person or company (5 letters, 4 digits, 1 letter).","AAAAA0000A","The PAN is embedded in the GSTIN and is needed for bank and customs registration.");
  add("HS Code / ITC-HS / HSN","hs code|hsn|hs|itc hs|itc hs code|tariff code|tariff heading|hsn code|hsn sac|classification|cth|customs tariff|tariff item","The Harmonised System code that classifies the product. The first 6 digits are international; India adds 2 more (8 digits, ITC-HS). It decides the duty rate, incentives and licensing rules.","10063020 (Basmati rice)","The HS code must be identical on the invoice, Shipping Bill and packing documents. A different code is treated as mis-declaration.");
  add("SAC","sac|service accounting code","Services Accounting Code \u2014 the 6-digit GST code for services (for example freight, warehousing) in the same way HSN is for goods.","996511 (goods transport by road)","");
  add("Port Code / Customs House Code","port code|customs house code|chc|customs port|location code|place code|unlocode","A code for a Customs location. Indian ports use the format INXXX1, for example INNSA1 (Nhava Sheva) or INMAA1 (Chennai Sea). International locations use UN/LOCODE (five letters, e.g. AEJEA for Jebel Ali).","INCOK1 = Cochin Sea","Customs systems read the code, not the port\u2019s name.");
  add("IFSC","ifsc|ifsc code","Indian Financial System Code \u2014 an 11-character code identifying a bank branch for domestic transfers (4 letters, a zero, 6 characters).","HDFC0001234","");
  add("SWIFT / BIC","swift|bic|swift code|swift bic|bank identifier","An 8- or 11-character international code that identifies a bank for cross-border payments.","HDFCINBBXXX","");
  add("IBAN","iban|international bank account number","International Bank Account Number \u2014 a standard account format used in Europe and the Gulf (the UAE\u2019s starts with AE and has 23 characters).","AE070331234567890123456","");
  add("Bank Account Number","account number|account no|a/c no|bank account|beneficiary account|account","The number of the bank account where money is to be received or paid.","","Check every digit \u2014 a wrong account number sends payment to the wrong place.");
  add("IMO Number","imo|imo number|imo no","A 7-digit number permanently given to a ship by the International Maritime Organization. Unlike a vessel\u2019s name it never changes.","9321483","");
  add("UN Number","un number|un no|un id|united nations number","A 4-digit number that identifies a dangerous substance for transport (for example UN1203 for petrol). It is printed on the Dangerous Goods Declaration and package labels.","UN1950 (aerosols)","");
  add("IATA Code / Airline Prefix","iata|iata code|airline prefix|airline code|airport code|iata airport","IATA gives airports a 3-letter code (BOM = Mumbai, DXB = Dubai) and airlines a 3-digit prefix used at the start of every Air Waybill number.","DXB, 176 (Emirates)","");
  add("SCAC","scac|standard carrier alpha code","Standard Carrier Alpha Code \u2014 a 2 to 4 letter code that identifies a shipping line or carrier in electronic messages.","MAEU = Maersk","");
  add("LEI / CIN / Registration Number","cin|company identification|registration number|reg no|incorporation|roc|company registration|corporate identity","Identifiers issued to the company by the Registrar of Companies. CIN is the 21-character Corporate Identity Number.","","");
  add("IRN (e-Invoice)","irn|invoice reference number|e invoice|einvoice|e-invoice","Invoice Reference Number \u2014 a 64-character code generated by the GST e-invoice portal when a tax invoice is registered. It proves the invoice is reported to the GST system.","","");
  add("E-Way Bill Number","eway bill|e way bill|ewb|eway bill number|ewaybill","A 12-digit electronic permit generated on the GST portal that must travel with goods worth more than the threshold when moved by road in India.","","");
  add("Lorry Receipt (LR) Number","lr number|lr no|lorry receipt|consignment note|cn number|gr number|goods receipt number|lr","The Lorry Receipt (also called consignment note or GR) is the transporter\u2019s receipt and contract of carriage for road cargo. Its number is quoted on invoices and PODs.","","");
  add("Bill of Lading Number","bl number|bl no|b l no|bill of lading number|bol number|b/l number|blno","The unique number of the Bill of Lading, assigned by the carrier or forwarder. It is quoted on the invoice, Shipping Bill, delivery order and arrival notice.","COSU2607004481","A wrong B/L number prevents release of cargo and payment under a Letter of Credit.");
  add("Booking Number","booking number|booking no|booking reference|booking ref|bkg","The carrier\u2019s reference for the space you booked on a vessel or flight. It links the shipping instruction, container release and Bill of Lading.","BKG2026004512","");
  add("AWB / MAWB / HAWB","awb|air waybill number|mawb|hawb|master air waybill|house air waybill|awb number","The Air Waybill number: 11 digits \u2014 a 3-digit airline prefix, a serial and a check digit. MAWB is issued by the airline, HAWB by the forwarder.","176-12345675","");
  add("Container Number","container number|container no|container id|cntr|container|equipment number","An 11-character ID painted on every container: 4 letters (owner code + U), 6 digits and 1 check digit (ISO 6346).","MSKU0000000","One wrong character and the terminal cannot find the box.");
  add("Seal Number","seal number|seal no|seal|bolt seal|customs seal|rfid seal|e seal|eseal","A numbered tamper-proof lock fitted on the container door after stuffing. A broken or different seal means the container may have been opened.","CK-558201","The seal number is recorded on the B/L, Container Packing Certificate and Seal Report.");
  add("Shipping Bill Number","shipping bill number|sb number|sb no|shipping bill no","The number Customs gives to an export Shipping Bill when it is filed on ICEGATE, with the filing date. It links the export to the Let Export Order, BRC and drawback claims.","","");
  add("Bill of Entry Number","bill of entry number|boe number|be number|boe no|be no","The number Customs gives to an import Bill of Entry. It is used for duty payment, Out-of-Charge and the delivery order.","","");
  add("IGM / EGM Number","igm|egm|import general manifest|export general manifest|igm number|egm number|line number|igm no","The IGM is the Import General Manifest filed by the carrier before arrival; the EGM is the Export General Manifest after loading. Each has a number and line items that Customs uses to track cargo.","","");
  add("Rotation Number","rotation number|rotation no|rotation|rot no","A number Customs gives to a vessel\u2019s arrival call at an Indian port. Import documents refer to the rotation number of the ship that brought the cargo.","","");
  add("Vehicle Registration Number","vehicle number|vehicle no|truck number|registration number|truck no|lorry number|vehicle registration|veh no","The truck\u2019s number plate, in the Indian RTO format: state code, district number, series letters and four digits.","KL07AB1234","It must be the same on the Lorry Receipt, e-way bill and gate pass.");

  /* ===== TRANSPORT & SHIPMENT ===== */
  add("Vessel Name","vessel|vessel name|ship name|mother vessel|feeder vessel|vessel flight|vessel/flight","The name of the ship carrying the cargo. Use together with the voyage number, because a ship makes many voyages.","MV SPECIMEN STAR","");
  add("Voyage Number","voyage|voyage number|voyage no|voy|voyage flight|flight number|flight no|flight","A code that identifies one particular sailing of a vessel (or the flight number for air). Vessel name + voyage number tells exactly which trip carries your cargo.","026E (the E often means eastbound)","A wrong voyage number puts your cargo on the wrong sailing in the manifest, so the arrival date and customs filing are wrong.");
  add("ETD / ETA / ATD / ATA","etd|eta|atd|ata|estimated time of departure|estimated time of arrival|actual time of departure|actual time of arrival|departure date|arrival date|sailing date|expected arrival|expected departure","ETD/ETA are the estimated departure and arrival dates; ATD/ATA are the actual ones. Arrival can never be earlier than departure.","ETD 20-Oct-2026, ETA 27-Oct-2026","These dates control the Letter of Credit shipment window, free days and the importer\u2019s clearance planning.");
  add("Port of Loading (POL)","port of loading|pol|loading port|port of load|origin port|port of origin|port of export|place of loading","The port where the cargo is put on the ship. For Indian exports it is also the port where Customs clears the Shipping Bill.","Cochin (INCOK1)","");
  add("Port of Discharge (POD)","port of discharge|pod|discharge port|destination port|port of destination|port of unloading|port of entry|port of arrival","The port where the vessel unloads the cargo. The importer\u2019s customs clearance happens here (unless the cargo moves on).","Jebel Ali (AEJEA)","");
  add("Place of Receipt / Place of Delivery","place of receipt|place of delivery|final destination|final place of delivery|delivery place|receipt place|place of acceptance","Place of receipt: where the carrier first takes the cargo (a factory or ICD for door-to-door shipments). Place of delivery: where the carrier hands it to the consignee. For port-to-port shipments they equal the ports.","","");
  add("Transhipment","transhipment|transshipment|transhipment port|port of transhipment|via port|transshipment port","Moving cargo from one ship to another at an intermediate port because no direct vessel serves the route.","Colombo","Each transhipment adds time and risk, and an LC must say \u201ctranshipment allowed\u201d.");
  add("FCL / LCL","fcl|lcl|full container load|less than container load|loose cargo|consolidation","FCL: one shipper fills a whole container. LCL: cargo from several shippers shares a container and is stuffed at a CFS.","","");
  add("TEU / FEU / Container Types","teu|feu|20gp|40gp|40hc|20 ft|40 ft|container type|container size|dry container|high cube|reefer|open top|flat rack|iso tank|size type|container size type","A TEU is one 20-foot container; a FEU is a 40-foot one. Common types: 20GP / 40GP (general purpose), 40HC (high cube, taller), reefer (refrigerated), open top, flat rack and ISO tank.","20GP, 40HC","");
  add("Gross Weight","gross weight|gross wt|gross|total gross weight|gross mass|gross kg","The weight of the goods plus all their packing (bags, cartons, pallets). Gross weight is never smaller than net weight.","20,160 kg","Freight, VGM and customs all use gross weight.");
  add("Net Weight","net weight|net wt|net|total net weight|net kg|nett weight","The weight of the goods alone, without packing.","20,000 kg","");
  add("Tare Weight","tare|tare weight|empty weight|tare wt","The weight of the empty container or empty vehicle (or of the packing alone).","2,200 kg for a 20ft container","Gross = tare + net cargo.");
  add("VGM (Verified Gross Mass)","vgm|verified gross mass|solas|vgm weight|verified weight|vgm method","Under the SOLAS rule every packed export container must have its total weight (cargo + packing + container) verified and declared to the carrier before loading. Method 1 weighs the packed container; Method 2 adds up the weights of cargo, packing and the empty container.","","A container without VGM is not loaded on the ship.");
  add("Measurement / CBM / Volume","cbm|measurement|volume|cubic metre|cubic meter|m3|dimension|dimensions|length width height|lwh|cubic","The space the cargo occupies, in cubic metres (length \u00d7 width \u00d7 height). Freight for light bulky cargo is charged on volume.","27.60 CBM","");
  add("Chargeable Weight / Volumetric Weight","chargeable weight|volumetric weight|volume weight|dimensional weight|dim weight","In air freight you pay on whichever is higher: the actual weight or the volumetric weight (volume in cm\u00b3 \u00f7 6000 for kg).","","");
  add("Packages / Kind of Package","packages|no of packages|number of packages|kind of package|package type|packing type|packing|pkgs|packaging|type of packing|number of pcs","How many separate pieces the cargo is packed in, and what they are (cartons, bags, pallets, drums, bales, crates).","800 bags","The package count is how Customs and the carrier count the cargo \u2014 it must match on all documents.");
  add("Marks & Numbers / Shipping Marks","marks and numbers|marks|shipping marks|marks and nos|carton marks","The identification printed on each package \u2014 usually buyer initials, destination, order number and carton numbers \u2014 so the receiver can match goods to documents.","GPF / DXB / MBR-20 / 1-800","");
  add("Description of Goods","description of goods|goods description|description|commodity|product description|cargo description|item description|nature of goods|product|goods","What the goods physically are, written clearly enough for Customs to classify them (material, grade, use). It must be the same on every document.","Basmati rice 1121, crop 2025-26, in 25 kg PP bags","");
  add("Stuffing / Destuffing","stuffing|destuffing|stuffing date|stuffing location|stuffing supervisor|factory stuffing|devanning","Stuffing is loading cargo into a container; destuffing is unloading it. Factory stuffing happens at the exporter\u2019s premises under a Customs officer or surveyor; CFS stuffing happens at the CFS.","","");
  add("Container Load Plan (CLP)","clp|container load plan|load plan|stowage|stowage plan|loading plan","A drawing/list of how cargo is arranged inside the container (what goes where) so weight is balanced and cargo is not damaged.","","");
  add("Lashing / Dunnage","lashing|dunnage|securing|blocking|bracing","Materials and methods used to hold cargo in place inside a container so it cannot shift during sea movement.","","");
  add("Cut-off (Gate / Document / VGM)","cut off|cutoff|gate cut off|document cut off|vgm cut off|si cut off|closing time|gate in cutoff","The last date and time the carrier accepts the container at the terminal, the shipping instructions or the VGM for a given sailing. Miss it and the cargo is \u201crolled\u201d to the next vessel.","","");
  add("Gate-In / Gate-Out","gate in|gate out|gate in date|gate out date|gate pass|in gate|out gate","The record when a container enters (gate-in) or leaves (gate-out) a terminal, CFS or depot. The gate pass authorises that movement.","","");
  add("Rolled Cargo / Shut-out","rolled|rolling|shut out|shutout|roll over|short shipment|short shipped","When the vessel is full or the cut-off was missed, the container is moved to a later sailing (rolled). A shut-out means it did not make the ship.","","");
  add("Routing / Transit Time","routing|route|transit time|transit|via|mode of transport|mode of shipment|shipment mode|transport mode|mode","The path the cargo takes and how long it takes. Mode means sea, air, road or rail (multimodal combines them).","","");
  add("Dangerous Goods (DG) / IMDG Class","dangerous goods|dg|imdg|hazardous|hazard class|class|packing group|flash point|flashpoint|proper shipping name|un class|hazmat|iata dgr","Goods that can harm people, ships or aircraft (flammable, toxic, corrosive, explosive\u2026). They have an IMDG/IATA class (1\u20139), a UN number, a packing group (I = great danger, III = minor danger) and need a Dangerous Goods Declaration.","Class 3 flammable liquid, UN1203, PG II","Wrongly declared dangerous goods can cause fires; carriers refuse or fine the shipper.");
  add("MSDS / SDS","msds|sds|safety data sheet|material safety data sheet","A manufacturer\u2019s sheet that lists a chemical\u2019s hazards, handling, storage and emergency measures. Carriers and terminals ask for it for chemical cargo.","","");
  add("Reefer / Temperature Control","reefer|temperature|set temperature|celsius|cold chain|refrigerated|genset|temp","A reefer is a refrigerated container. The set temperature (\u00b0C) is the temperature the cargo must be held at during the voyage.","-18\u00b0C for frozen fish","");

  /* ===== FREIGHT & CHARGES ===== */
  add("Freight Terms (Prepaid / Collect)","freight prepaid|freight collect|freight terms|prepaid|collect|freight payable|payable at|freight payable at","Prepaid: the shipper pays the carrier\u2019s freight at the origin (typical for CIF/CFR/CPT sales). Collect: the consignee pays freight at destination (typical for FOB/EXW).","","");
  add("Freight Charges / Rate","freight|freight charges|freight rate|ocean freight|air freight|freight amount|basic freight|freight cost|rate per kg|rate per container|all in rate","The price the carrier charges to move the cargo \u2014 per container, per tonne/CBM or per kg for air. Other charges are added as surcharges.","USD 1,450 per 20ft","");
  add("THC / BAF / CAF / Surcharges","thc|baf|caf|lss|pss|surcharge|surcharges|terminal handling charge|bunker adjustment|currency adjustment|isps|peak season|emergency|doc fee|documentation fee|handling charges|other charges","Extra charges on top of the basic freight: Terminal Handling Charge (THC) at the port, Bunker Adjustment Factor (BAF, fuel), Currency Adjustment Factor (CAF), Low Sulphur Surcharge (LSS), Peak Season Surcharge (PSS) and others.","","");
  add("Demurrage / Detention / Free Days","demurrage|detention|free days|free time|free period|per diem|storage charges|late fee|dnd","Free days are the period you may keep a container at the terminal (demurrage) or outside it (detention) without charge. After that, daily charges apply.","7 free days, then USD 50 per day","");
  add("Lump Sum / Minimum Charge","lump sum|minimum charge|minimum|min charge|slab","A fixed price for the whole job, or the smallest amount a carrier will charge regardless of weight.","","");

  /* ===== INCOTERMS ===== */
  add("Incoterms\u00ae 2020","incoterm|incoterms|terms of delivery|delivery terms|trade terms|terms of sale|delivery term|inco term","International rules that say who pays for transport and insurance and where the risk passes from seller to buyer. The 11 terms are EXW, FCA, FAS, FOB, CFR, CIF, CPT, CIP, DAP, DPU and DDP.","FOB Cochin, CIF Jebel Ali","The same Incoterm and named place must appear on the contract, invoice and LC.");
  add("EXW \u2014 Ex Works","exw|ex works","The seller makes the goods available at their own premises. The buyer arranges and pays for everything else, including loading and export clearance.","","");
  add("FCA \u2014 Free Carrier","fca|free carrier","The seller delivers the goods, cleared for export, to the carrier or place the buyer names. Risk passes at that point.","","");
  add("FAS \u2014 Free Alongside Ship","fas|free alongside ship","The seller delivers the goods alongside the vessel at the named port. Sea transport only.","","");
  add("FOB \u2014 Free On Board","fob|free on board|fob value","The seller delivers the goods on board the vessel at the port of loading and clears them for export. Risk passes once the goods are on board; the buyer pays ocean freight and insurance. Sea transport only.","FOB Cochin","FOB value (goods price without freight/insurance) is what Indian Customs and incentives use for exports.");
  add("CFR \u2014 Cost and Freight","cfr|cost and freight|c f r","The seller pays the sea freight to the destination port, but the buyer bears the risk from when the goods are on board and buys the insurance.","","");
  add("CIF \u2014 Cost, Insurance and Freight","cif|cost insurance and freight|cif value|c i f","Like CFR, but the seller also buys marine insurance (usually for 110% of the invoice value) for the buyer\u2019s benefit.","CIF Jebel Ali","");
  add("CPT \u2014 Carriage Paid To","cpt|carriage paid to","The seller pays the freight to the named destination; risk passes when the goods are handed to the first carrier. Any transport mode.","","");
  add("CIP \u2014 Carriage and Insurance Paid To","cip|carriage and insurance paid to","Like CPT, plus the seller buys cargo insurance (at the higher \u201cAll Risks\u201d level, ICC A, under Incoterms 2020).","","");
  add("DAP \u2014 Delivered at Place","dap|delivered at place","The seller delivers the goods ready for unloading at the named place in the buyer\u2019s country and bears all risk until then. The buyer clears import.","","");
  add("DPU \u2014 Delivered at Place Unloaded","dpu|delivered at place unloaded|dat|delivered at terminal","The seller delivers and also unloads the goods at the named place (this term replaced DAT in 2020).","","");
  add("DDP \u2014 Delivered Duty Paid","ddp|delivered duty paid","The seller carries the maximum responsibility: delivers to the buyer\u2019s door with import clearance done and import duties paid.","","");

  /* ===== CUSTOMS & DUTIES ===== */
  add("Shipping Bill","shipping bill|sb|export declaration|sb date|shipping bill date|let export order|leo","The export declaration filed with Customs (through ICEGATE) for every export shipment from India. After checking, Customs gives a Let Export Order (LEO) allowing the cargo to be loaded.","","");
  add("Bill of Entry","bill of entry|boe|be|import declaration|bill of entry date|self assessment|assessment","The import declaration filed with Customs by the importer or their CHA to declare the goods, pay duty and get them cleared.","","");
  add("Let Export Order (LEO)","leo|let export order|leo date|export order","The permission Customs gives after examining/clearing a Shipping Bill. Only after LEO can the container be loaded onto the vessel.","","");
  add("Out of Charge (OOC)","ooc|out of charge|out of charge date|ooc date|customs release|clearance order","The order by which Customs finally releases imported cargo after duty is paid. The importer can then take delivery.","","");
  add("Customs Duty (BCD, IGST, SWS)","customs duty|duty|bcd|basic customs duty|sws|social welfare surcharge|igst|import duty|total duty|duty amount|duty payable|aidc|cvd|countervailing|anti dumping|add|safeguard","Taxes on imported goods: Basic Customs Duty (BCD) on the assessable value, Social Welfare Surcharge (SWS) on the BCD, and IGST on value + BCD + SWS. Anti-dumping or safeguard duty may be added for specific goods.","","Duty is calculated from the assessable value and the HS code\u2019s tariff rate.");
  add("Assessable Value / Transaction Value","assessable value|transaction value|av|customs value|value for duty|valuation|declared value|insurance and freight|landing charges|cif value|cost insurance freight|exchange rate|notified rate|rate of exchange|exchange rate used|conversion rate","The value on which import duty is charged: price paid + freight + insurance (+ landing charges, usually 1%), converted to INR at the CBIC-notified exchange rate.","","");
  add("Duty Drawback / RoDTEP / RoSCTL","drawback|duty drawback|dbk|rodtep|rosctl|incentive|export incentive|mei s|refund of duty|drawback amount|scrip","Government export incentives that refund embedded taxes: Duty Drawback (customs duty on inputs), RoDTEP (remission of duties and taxes on exported products) and RoSCTL (state and central levies on apparel/textiles).","","Claimed through the Shipping Bill using the correct HS code and the IEC.");
  add("SEZ / EOU","sez|special economic zone|eou|export oriented unit|stpi|free trade zone|ftwz","Special Economic Zones and Export Oriented Units are areas/units given tax and customs benefits to produce and export goods or services.","","");
  add("Advance Authorisation / DFIA / EPCG","advance authorization|advance authorisation|aa|dfia|epcg|advance license|export obligation|eo|authorisation number|license number|authorization number|licence number|sion","DGFT schemes that allow duty-free import of raw materials (Advance Authorisation, DFIA) or capital goods (EPCG) against a promise to export.","","");
  add("LUT \u2014 Letter of Undertaking","lut|letter of undertaking|bond|export under lut|lut number|lut arn|igst refund|zero rated|zero-rated","A declaration to the GST department that lets an exporter ship goods without paying IGST first (zero-rated supply). Without a valid LUT the exporter must pay IGST and claim a refund.","","");
  add("ARE-1","are 1|are1|central excise|excise|excise seal|excise bond|rebate claim","The form used for exports of excisable goods under central excise to claim rebate/exemption; it records examination and sealing.","","");
  add("ICEGATE / EDI / ICES","icegate|edi|ices|electronic data interchange|e filing|e-filing|customs portal|icegate id|edi copy|ack|acknowledgement","ICEGATE is the Government\u2019s portal for e-filing customs documents. EDI means the data is exchanged electronically with the Customs system (ICES), which gives acknowledgement numbers.","","");
  add("Examination / Risk Management (RMS)","examination|inspection|rms|risk management|exam|physical examination|first check|prior check|green channel|out of charge examination|surveyor|survey","Customs may physically examine cargo (or only check documents) depending on risk assessment. The Examination Report records what was found.","","");
  add("Country of Origin","country of origin|origin country|made in|origin|coo|manufacturing country|country of manufacture|manufactured in","The country where the goods were produced or substantially transformed. It decides duty rates under trade agreements and is certified by a Certificate of Origin.","India","");
  add("Certificate of Origin (COO)","certificate of origin|preferential|non preferential|fta|free trade agreement|gsp|form a|rcmc|chamber of commerce|issuing authority","A certificate that confirms the goods\u2019 origin. A preferential COO (under an FTA, or GSP Form A) can give lower import duty; a non-preferential COO simply states origin.","","");
  add("Export Promotion Council / RCMC","rcmc|export promotion council|epc|apeda|mpeda|spices board|tea board|coffee board|registration cum membership","Export Promotion Councils and commodity boards (APEDA, MPEDA, Spices Board\u2026) register exporters. The Registration-cum-Membership Certificate (RCMC) proves you are registered.","","");
  add("SCOMET / Restricted Items","scomet|restricted|prohibited|licence required|permit required|dual use|export license|import license|import permit|export permit|noc|no objection|licensing","SCOMET lists sensitive items (dual-use goods, chemicals, technology) that need a DGFT licence to export. Other goods may be restricted or prohibited and need a licence or permit.","","");
  add("Phytosanitary / Plant Quarantine","phytosanitary|plant quarantine|pq|quarantine|fumigation|fumigation certificate|methyl bromide|aluminium phosphide|phosphine|treatment|fumigant","A Phytosanitary Certificate from the plant quarantine authority proves plant products are free from quarantine pests. Fumigation is a treatment (with fumigants like methyl bromide or phosphine) that kills pests; a Fumigation Certificate records it.","","");
  add("Health / Halal / HACCP / Catch Certificate","health certificate|halal|kosher|haccp|catch certificate|food safety|fssai|eic|export inspection council|animal quarantine|veterinary|sanitary","Food and animal products need certificates that prove they are safe and lawfully produced: Health Certificate, HACCP (food-safety system), Halal/Kosher (religious standards) and Catch Certificate (fish caught legally).","","");
  add("Certificate of Analysis / Inspection","certificate of analysis|coa|inspection certificate|quality certificate|pre shipment inspection|psi|lab test|test report|specification|quality|analysis|assay","Reports from a laboratory or inspection agency that confirm the goods\u2019 quality, quantity or specification matches the contract.","","");
  add("Security Declaration / ISF (10+2)","security declaration|isf|importer security filing|10 2|known shipper|regulated agent|screening|x ray|ispf","Security filings that tell the carrier/authority the cargo is safe. ISF (10+2) is the US customs pre-arrival filing by the importer; air cargo needs a security declaration from a known shipper or regulated agent.","","");
  add("Transshipment Permit / Bonded","transshipment permit|bonded|bond|warehouse bill of entry|ex bond|in bond|bonded warehouse|customs bond","Permission to move cargo under Customs control from one place to another (or through India) without paying duty until it is cleared or re-exported.","","");

  /* ===== TRADE FINANCE & PAYMENT ===== */
  add("Letter of Credit (LC)","letter of credit|lc|documentary credit|lc number|lc no|credit number|mt700|ucp 600|ucp|irrevocable|revolving|transferable|standby|lc type|credit type|documentary","A bank\u2019s written promise (issued for the buyer) to pay the seller if the seller presents documents that strictly comply with the LC\u2019s terms. It is governed by the UCP 600 rules.","","The bank checks documents, not goods \u2014 any mismatch is a discrepancy and can stop payment.");
  add("LC Dates (Latest Shipment / Expiry / Presentation Period)","latest shipment date|expiry date|date of expiry|presentation period|lc expiry|shipment period|validity|valid until|latest date|expiry|expiry place|available by","Latest shipment date: the last day the goods may be shipped. Expiry date: the last day documents can be presented to the bank. Presentation period: how many days after shipment documents must reach the bank (often 21).","","");
  add("Partial Shipment / Transhipment Allowed","partial shipment|partial shipments|transhipment allowed|partial|shipments allowed","Whether the LC permits the goods to be sent in more than one shipment, or to change ships on the way.","Partial shipments: not allowed","");
  add("Documents Required (LC)","documents required|required documents|lc documents|docs required|original|copies|number of copies|full set|set of","The list of documents the LC says must be presented (invoice, packing list, B/L, certificate of origin\u2026) and how many originals/copies of each.","","");
  add("Discrepancy","discrepancy|discrepancies|discrepant|waiver|waive|refusal","A difference between a presented document and the LC (or between two documents). The bank can refuse payment until it is corrected or the buyer waives it.","","");
  add("Bill of Exchange (Draft)","bill of exchange|draft|boe draft|sight draft|usance|tenor|at sight|days after|bill of exchange number|sight|usance bill|maturity|due date|acceptance","A written order from the exporter (drawer) telling the buyer or a bank (drawee) to pay a fixed amount \u2014 at sight (on presentation) or after a period (usance, e.g. 90 days after B/L date).","","");
  add("Payment Terms (Advance / Open Account / DP / DA / TT)","payment terms|payment term|payment method|terms of payment|advance payment|advance|open account|documentary collection|dp|da|d p|d a|cad|cash against documents|tt|telegraphic transfer|wire transfer|net 30|net 60|credit period|payment mode|mode of payment|payment due","How and when the buyer pays. Advance: before shipment. Open account: after delivery (e.g. Net 60). Documents against payment (DP): buyer pays to get the documents. Documents against acceptance (DA): buyer accepts a draft payable later. LC: bank-backed. TT: bank wire transfer.","","");
  add("FIRC / BRC / eBRC / Realisation","firc|brc|ebrc|bank realization certificate|bank realisation certificate|realization|realisation|export proceeds|remittance|fema|proceeds|realised|remittance date|inward remittance","The Foreign Inward Remittance Certificate (FIRC) proves money came from abroad. The e-BRC (Bank Realisation Certificate) is issued by the bank once export proceeds are received, and is needed for DGFT/Customs incentives and GST refund.","","");
  add("Bank Guarantee (BG)","bank guarantee|bg|bg number|performance guarantee|bid bond|advance payment guarantee|guarantee amount|guarantee|bg type|margin","A bank\u2019s promise to pay a stated amount if the customer fails to meet an obligation (for example to deliver, or to repay an advance).","","");
  add("Marine Insurance","marine insurance|insurance|insurance certificate|insurance policy|policy number|policy no|insured|sum insured|insured value|premium|insurer|insurance company|coverage|institute cargo clauses|icc a|icc b|icc c|all risks|open cover|cover note|assured|claim","Insurance for cargo during transit. Standard cover is the Institute Cargo Clauses (A = all risks, B, C = limited). The sum insured is normally 110% of the CIF value. A Certificate or Policy is the evidence.","Sum insured USD 25,300 (110% of 23,000)","");
  add("Marine Claim / Survey / Damage","claim|claim number|claim amount|survey report|surveyor|loss|damage|damage report|shortage|short landing|salvage|subrogation|damaged|loss adjuster|deductible|excess|general average","What follows if cargo is lost or damaged: a surveyor records the damage, the insured files a claim with the insurer, and the insurer pays after checking the policy cover.","","");
  add("Letter of Indemnity (LOI)","loi|letter of indemnity|indemnity|indemnify","A promise to compensate the carrier for loss if it does something outside normal rules \u2014 for example releasing cargo without the original Bill of Lading.","","");
  add("Credit Note / Debit Note","credit note|debit note|cn|dn|adjustment note|reason for credit|reason for debit|original invoice","A credit note reduces the amount a customer owes (return, discount, error). A debit note increases it (extra charge, undercharge). Both refer to the original invoice.","","");
  add("Currency","currency|currency code|invoice currency|payment currency|ccy|usd|eur|inr|aed|gbp","The money in which the invoice or payment is expressed (USD, EUR, AED, INR\u2026). One shipment is normally invoiced in a single currency.","USD","");
  add("Invoice Value / Amount","invoice value|amount|total amount|grand total|total value|subtotal|net amount|line total|total|value|amount in words|total invoice value|amount payable|amount due|balance","The total money value of the goods (and charges) on the invoice. Unit price \u00d7 quantity gives each line total; the lines plus freight/insurance/tax give the grand total.","USD 23,000.00","");
  add("Unit Price / Quantity / Unit","unit price|price per unit|rate|unit rate|quantity|qty|unit|uom|unit of measure|unit of measurement|per unit|number of units|ordered quantity|shipped quantity|received quantity","Quantity is how much is shipped; the unit says what it is counted in (KGS, MT, PCS, CTN\u2026); the unit price is the money for one unit.","20 MT at USD 1,150 per MT","Mixing units (MT vs KG) is a common thousand-fold error.");
  add("Discount / Tax / Round Off","discount|tax|taxable value|round off|rounding|tax amount|cgst|sgst|igst rate|tax rate|gst rate|rate of tax|cess|tcs|tds","Discount reduces the price; tax (GST) is added on the taxable value; round-off adjusts the total to a whole rupee.","","");

  /* ===== GST & FINANCE DOCUMENTS ===== */
  add("Tax Invoice (GST)","tax invoice|gst invoice|invoice number|invoice no|invoice date|place of supply|reverse charge|rcm|supply|state code|invoice type|b2b|b2c","A GST tax invoice shows the supplier\u2019s and buyer\u2019s GSTIN, HSN code, taxable value, GST rate and amount, and the place of supply. Within one state it carries CGST + SGST; between states (or exports) it carries IGST.","","");
  add("Place of Supply","place of supply|pos|state of supply|supply state|delivery state|state","The state (or country) where the supply is treated as taking place; it decides whether CGST+SGST or IGST applies.","","");
  add("Input Tax Credit (ITC)","itc|input tax credit|input credit|gst credit","The GST a business paid on purchases that it can set off against the GST it collects on sales.","","");
  add("Invoice Number / Reference Number","invoice number|reference number|reference no|ref no|ref|document number|doc no|document no|number|serial number|sr no|document reference|ref number|control number","The unique number of this document, usually in a fixed pattern (for example INV-2026-0001). Other documents of the same shipment quote it.","INV-2026-0001","");
  add("Payment Voucher / Vendor Bill","payment voucher|vendor bill|supplier invoice|payable|payment advice|cheque|utr|neft|rtgs|transaction reference|utr number|payment reference|voucher number|voucher|cheque number|bank reference|three way match|3 way match","A voucher records money paid out; a vendor bill is the supplier\u2019s invoice you owe. Finance matches bill, purchase order and goods receipt (three-way match) before paying; the UTR is the bank\u2019s reference for the transfer.","","");

  /* ===== ROAD ===== */
  add("Trip Sheet / Freight Memo / POD","trip sheet|freight memo|pod|proof of delivery|delivered|receiver name|received by|delivery date|delivery time|trip|driver|driver name|licence|driving licence|driver mobile|helper|odometer|km|distance|route|origin|destination|loading point|unloading point","A trip sheet logs one truck trip (driver, route, distance, expenses). A freight memo records the freight agreed with the transporter. Proof of Delivery (POD) is the receiver\u2019s signed acknowledgement that goods arrived.","","");
  add("E-Way Bill (details)","e way bill|eway|ewb|validity|valid till|valid upto|transporter id|transporter gstin|transport document number|supply type|document type|approximate distance|from state|to state|consignor|consignee gstin","An electronic permit generated on the GST portal before goods worth more than the threshold are moved by road. It carries consignor/consignee GSTIN, HSN, value, vehicle number and distance, and has a validity period based on distance.","","");
  add("Toll / Fuel / Weighbridge","toll|toll receipt|toll plaza|fuel|fuel slip|litres|liters|diesel|fuel rate|fuel amount|pump|weighbridge|weighbridge slip|loaded weight|unloaded weight|kanta|axle","Cost and weight records for a truck trip: toll paid at plazas, fuel bought at a pump (litres \u00d7 rate), and weights recorded at a weighbridge with the truck loaded and empty (net = loaded \u2212 empty).","","");
  add("Vehicle Types / Fitness / Permit","vehicle type|truck type|lcv|hcv|mcv|trailer|container truck|tipper|vehicle capacity|capacity|fitness|permit|national permit|insurance validity|puc|rc|registration certificate|vehicle inspection|tyre|brake|condition","Trucks are classed by size and capacity (LCV light, MCV medium, HCV heavy, trailer, containerised). A vehicle needs a valid RC, fitness certificate, insurance, PUC and the right goods-carriage permit.","","");
  add("FTL / LTL","ftl|ltl|full truck load|less than truck load|part load|full load","FTL: one customer books a whole truck. LTL: several customers\u2019 smaller consignments share one truck.","","");
  add("Delivery Challan / Gate Pass","delivery challan|challan|gate pass|dispatch|dispatched|outward|inward|material gate pass|returnable|non returnable|reason for transport|job work","A challan accompanies goods moved without a sale (samples, job work, transfers). A gate pass authorises goods or vehicles to enter or leave premises.","","");

  /* ===== WAREHOUSE ===== */
  add("GRN \u2014 Goods Receipt Note","grn|goods receipt note|goods receipt|received|received quantity|accepted quantity|rejected quantity|short|excess|receiving|receipt date|inspection status|qc|quality check|po number|purchase order","The warehouse\u2019s record that goods arrived: how many were received, accepted or rejected against the purchase order. It triggers payment to the vendor.","","");
  add("Goods Issue / Picking / Dispatch","goods issue|gin|picking|picking slip|pick list|picked|picker|pick|issue note|issued|issue date|issued by|dispatch note|dispatch|packed|packer|staging|wave|order picking","Picking is taking the ordered items from storage locations; the goods issue note records stock leaving the warehouse; the dispatch note lists what was sent out with the vehicle.","","");
  add("Put-away / Bin / Storage Location","put away|putaway|bin|bin card|bin number|bin location|rack|aisle|shelf|location|storage location|zone|slot|storage|warehouse|warehouse location|pallet position|rack number","Put-away is moving received goods to their storage location. A bin (rack/shelf/slot) has a code so goods can be found; the bin card records every movement in or out of that bin.","A-03-02 (aisle A, rack 3, level 2)","");
  add("Stock Transfer / Cycle Count / Inventory","stock transfer|sto|transfer|from warehouse|to warehouse|cycle count|physical count|system quantity|physical quantity|variance|counted|counter|recount|inventory|stock|stock quantity|on hand|opening stock|closing stock|reorder|reorder level|safety stock","A stock transfer moves inventory between warehouses. A cycle count compares the system quantity with the physically counted quantity; the difference is the variance, which must be investigated.","","");
  add("SKU / Batch / Lot / Expiry","sku|stock keeping unit|item code|material code|part number|batch|batch number|lot|lot number|mfg date|manufacturing date|expiry|expiry date|best before|shelf life|serial|serial number|fifo|fefo|lifo","An SKU is the unique code of a product variant. Batch/lot numbers trace production runs; manufacturing and expiry dates drive shelf-life rules such as FIFO (first in, first out) and FEFO (first expiry, first out).","","");
  add("Inventory Valuation","valuation|inventory valuation|weighted average|moving average|standard cost|fifo valuation|stock value|closing value|valuation method|cost price|unit cost|total cost","How stock is valued in the books: FIFO, weighted-average or standard cost. Stock value = quantity \u00d7 unit cost under the chosen method.","","");
  add("Warehouse Receipt","warehouse receipt|warehouse keeper|warehouse|bonded|storage period|storage charges|warehouse charges|receipt number|warehouse receipt number|storage rate","A document issued by the warehouse keeper confirming goods are stored there, in what quantity and condition, and under what charges. It can be used as security for bank finance.","","");
  add("Quarantine / Damage","quarantine|hold|on hold|damage|damaged|condition|condition of goods|cause of damage|quantity damaged|claim|remarks on condition|breakage|leakage|pilferage|wet|shortage","Damaged or doubtful stock is separated (quarantine) and recorded in a Damage Report with quantity, cause and photos, so a claim can be made on the carrier, insurer or vendor.","","");

  /* ===== PROCUREMENT ===== */
  add("Purchase Requisition / RFQ / PO","purchase requisition|pr|rfq|request for quotation|quotation|quote|purchase order|po|po date|requisition|requested by|required date|required by|need by|approval|approved by|approver|budget|cost center|department","The procurement chain: a department raises a Purchase Requisition (PR), buyers send an RFQ to suppliers, compare quotations, and issue a Purchase Order (PO) to the chosen supplier.","","");
  add("Vendor / Supplier Evaluation","vendor|vendor code|vendor name|vendor master|supplier evaluation|rating|score|evaluation|criteria|weightage|vendor comparison|l1|lowest|approved vendor|vendor category|msme|payment terms vendor|delivery performance|quality rating","A vendor master holds each approved supplier\u2019s details (code, tax IDs, bank, terms). Suppliers are scored on price, quality and delivery; L1 is the lowest bidder.","","");
  add("Lead Time / MOQ / Delivery Terms","lead time|moq|minimum order quantity|delivery time|delivery schedule|delivery date|promised date|delivery terms|expected delivery|delivery period|schedule","Lead time is how long a supplier takes from order to delivery; MOQ is the smallest quantity a supplier will sell; the delivery date and terms say when and where the goods must arrive.","","");

  /* ===== AIR FREIGHT ===== */
  add("ULD / Air Cargo Acceptance","uld|unit load device|uld number|uld type|pallet|container uld|cargo acceptance|acceptance|accepted|known shipper|screening|build up|bup|air cargo|cargo terminal|ct|flight schedule|airline|schedule|aircraft|freighter|belly|origin airport|destination airport|airport","A ULD is the pallet or container used to load air cargo. Cargo is accepted at the airline\u2019s cargo terminal after screening, then built up into ULDs for the flight.","","");

  /* ===== DOCUMENTS (what each one is) ===== */
  add("Bill of Lading (B/L)","bill of lading|b l|bol|bl|house bill of lading|master bill of lading|hbl|mbl|original bl|telex release|surrender|to order|straight bl|clean bl|shipped on board|received for shipment|bl date|bill of lading date|date of issue bl|number of original|originals|seaway bill|waybill","The carrier\u2019s receipt for the cargo, the contract of carriage and (if negotiable) a document of title. \u201cShipped on board\u201d shows loading; \u201cclean\u201d means no damage was noted. A Master B/L is issued by the shipping line, a House B/L by the forwarder.","","");
  add("Sea Waybill","sea waybill|swb|seaway bill|non negotiable|express release","A non-negotiable receipt for sea cargo: the goods are delivered to the named consignee without presenting an original, so cargo moves faster than with a B/L.","","");
  add("Commercial Invoice / Proforma Invoice","commercial invoice|proforma invoice|proforma|pro forma|invoice|quotation invoice|export invoice|sales invoice|invoice date|supplier invoice|import invoice|original invoice","The commercial invoice is the seller\u2019s bill for the goods \u2014 the basis for customs value and payment. A proforma invoice is a preliminary \u201cquote-like\u201d invoice sent before shipment (to get an LC or advance payment).","","");
  add("Packing List","packing list|packing slip|pl|package number|carton number|carton no|pallet number|packed by|packing date|packing details|inner pack|outer pack","A list showing how the goods are packed: number of packages, what is in each, and weights and dimensions. The carrier, Customs and receiver use it to check the cargo.","","");
  add("Sales Order / Purchase Order","sales order|so number|so no|order number|order date|customer po|sold to|ship to party|order status|confirmation|order confirmation|ordered|order type|order value","A Sales Order is the seller\u2019s internal record of a customer\u2019s confirmed order; a Purchase Order is the buyer\u2019s order to the supplier. The order number links all later documents.","","");
  add("Shipping Instructions / Shipping Order","shipping instructions|si|shipping order|so release|release order|booking request|instructions to carrier|special instructions|handling instructions|remarks to carrier","The shipper\u2019s instructions to the carrier or forwarder on how to prepare the Bill of Lading (parties, cargo, weights, freight terms). The shipping order authorises loading.","","");
  add("Dock Receipt / Mate Receipt","dock receipt|mate receipt|mate s receipt|mr|received on board|chief officer|master|tally|tally sheet|tally clerk|cargo received|condition on receipt|remarks mate","A dock receipt records cargo received at the terminal; a mate\u2019s receipt is signed by the ship\u2019s officer when cargo is loaded and is exchanged for the Bill of Lading.","","");
  add("Delivery Order / Arrival Notice","delivery order|do|arrival notice|an|notice of arrival|consignee notified|do number|do date|release|release date|delivery order validity|valid till|do validity|ocean freight paid|freight paid|original bl surrendered|unload|discharge date|eta destination","The arrival notice tells the consignee that cargo has reached (or will reach) the destination. After paying charges and surrendering the original B/L the importer receives a Delivery Order that lets the terminal release the cargo.","","");
  add("Equipment Interchange Receipt (EIR)","eir|equipment interchange|equipment interchange receipt|interchange|damage on container|container condition|empty return|empty pick up|pick up|return|depot|container yard","A receipt issued when a container enters or leaves a terminal or depot. It records the container\u2019s condition, so damage is attributed to the right party.","","");
  add("Multimodal / Forwarder\u2019s Cargo Receipt","multimodal|mtd|mto|multimodal transport|fcr|forwarder s cargo receipt|combined transport|through bill|door to door|carrier s responsibility","A Multimodal Transport Document covers a journey by more than one mode (for example truck + ship + truck) under one contract. An FCR is a forwarder\u2019s receipt that it has taken charge of the goods.","","");
  add("Cargo Manifest","cargo manifest|manifest|manifest number|manifest date|vessel manifest|line no|item no|igm line|sub line|master|house","A list of all cargo carried on a vessel or flight, prepared by the carrier and filed with Customs (IGM for imports, EGM for exports).","","");
  add("SOFTEX","softex|software export|software|stp|stpi|it services|software services|service export","SOFTEX is the declaration exporters of software or IT services file with the STPI/RBI-designated authority so export proceeds can be tracked and certified.","","");

  /* ===== GENERIC FORM WORDS (so even simple fields get a clear meaning) ===== */
  add("Date / Time","date|time|date of issue|issue date|issued on|dated|timestamp|as on","Enter the date (and time, where asked) at which the event on this document actually happened or the document was issued. The date must be logical against the other documents of the shipment.","","");
  add("Place of Issue","place of issue|issued at|issued place|place|city|location","The city or location where this document was issued or signed.","Kochi","");
  add("Address","address|registered address|office address|street|city|state|pin|pincode|zip|postal|postal code|country|contact address|delivery address|warehouse address","Write the full postal address: premises/building, street, city, state, PIN or postal code and country. It should be the same on every document of the shipment.","","");
  add("Contact Person / Phone / Email","contact|contact person|phone|mobile|telephone|tel|email|e mail|fax|website|contact number|contact details|phone number|mobile number|email id","The person at the company who can be contacted about this document, with a working phone number and e-mail.","","");
  add("Name of Company","company name|name of company|party name|firm|firm name|organisation|organization|legal name|trade name|business name|name of exporter|name of importer|name|full name","The legal name of the company exactly as in its registration (for example \u201cPvt Ltd\u201d or \u201cPrivate Limited\u201d as registered).","","");
  add("Remarks / Notes","remarks|note|notes|comments|additional information|special instructions|declaration|remark|reason|reason for|purpose|description of reason|observations","Free-text space for anything the document should record that has no other box: conditions, special instructions or reasons.","","");
  add("Status / Verified / Confirmed / Checked","status|verified|confirmed|checked|approved|completed|ok|yes no|acknowledged|received|accepted|rejected|pending|pass|fail|result|compliance|compliant|satisfactory|available|applicable|required|tick|confirm|verify|certify|i certify|i declare|declaration accepted|validate|validated|information entered|accurate and complete|ready for filing|mandatory fields","These are confirmation boxes: by choosing or ticking them you state that you have personally checked that point. In a real office, ticking something you did not check can make you liable.","","");
  add("Signature / Stamp / Seal","signature|stamp|company stamp|seal|rubber stamp|official stamp|authorised stamp|digital signature|dsc|signed|signing|sign","A signature (and company stamp) proves the document was approved by an authorised person. Digital documents use a Digital Signature Certificate (DSC).","","");
  add("Prepared / Checked / Approved By","prepared by|checked by|approved by|issued by|verified by|received by|submitted by|filed by|entered by|reviewed by|authorized by|authorised by|handled by|created by|operator","The people who made, checked and approved the document. Real offices keep these separate (maker-checker) to catch errors.","","");
  add("Copies / Original / Duplicate","copies|original|duplicate|triplicate|number of copies|number of originals|copy|copy type|original copy|set|duplicates|nn copies|full set","Many documents are issued in sets \u2014 originals (valuable, negotiable) and non-negotiable copies. Banks usually need the full set of originals.","3 originals + 3 copies","");
  add("Revision / Version / Amendment","revision|version|amendment|amended|amendment number|revised|supersede|supersedes|replaces|cancellation|cancelled|cancel","When a document is changed after issue it gets a revision/amendment number so everyone uses the latest version.","","");


  /* ===== LONG-TAIL: safety data sheets, cargo-handling checklists, records, charges, quality ===== */
  add("Safety Data Sheet sections (hazards, toxicity, first aid)","acute toxicity|ld50|lc50|toxicity|carcinogenicity|germ cell mutagenicity|aspiration hazard|aquatic toxicity|endocrine|hazard statement|h codes|precautionary statement|p codes|pictogram|nfpa 704|nfpa|hazard class|hazard category|hazards not otherwise classified|hnoc|proposition 65|first aid|symptoms|effects|ingestion|inhalation|skin contact|eye contact|delayed symptoms|most important symptoms","The 16-section Safety Data Sheet (SDS) describes a chemical\u2019s dangers: toxicity values (LD50 = oral/dermal dose, LC50 = inhalation concentration that kills half of test animals), GHS pictograms, H-codes (hazard statements) and P-codes (precautionary statements), NFPA 704 \u201cfire diamond\u201d ratings and first-aid measures. Copy these from the manufacturer\u2019s SDS \u2014 never invent them.","H225 \u2014 Highly flammable liquid and vapour","Carriers, terminals and emergency teams rely on them if there is a spill or fire.");
  add("SDS: physical & chemical properties","boiling point|melting point|freezing point|flash point|odor|odour|odor threshold|physical characteristics|chemical characteristics|chemical stability|incompatible materials|partition coefficient|log kow|mobility in soil|persistence|degradability|bioaccumulative|ozone depletion|impurities|additives|stabilizing|mixture or substance|concentration|physical state|appearance","The properties of the chemical (state, colour, smell, boiling/melting point, stability, what it reacts with). They tell handlers how to store, stow and respond to the substance.","","");
  add("SDS: handling, spills, disposal & protection","personal precautions|environmental precautions|methods for containment|methods for clean up|clean up|recommended absorbent|protective equipment|ppe|hand protection|eye face protection|engineering controls|occupational exposure|oel|tlv|pel|exposure limit|safe handling|hygiene measures|disposal|waste|spill|prevention of secondary hazards|environmental exposure","How to handle the chemical safely and what to do if it leaks: protective equipment (gloves, goggles), ventilation, containment, absorbent materials and legal disposal methods.","","");
  add("Cargo securing & handling checklist","secured|cargo secured|load secured|lashed|blocked|braced|movement prevented|cargo movement|heavy cargo loaded first|loaded in delivery sequence|empty spaces filled|void|forklift|crane|equipment used|handling equipment|handling labels|labels applied|labels attached|orientation arrows|this side up|do not stack|fragile|handle with care|stack|cartons sealed|closures secured|overpack|previous labels removed|packaging|packed|load|loading area|brought to loading|released for loading|cargo released","Checklist items confirming cargo was loaded, blocked and labelled so it cannot shift or be damaged: heavy goods at the bottom/front, gaps filled, fragile and \u201cthis side up\u201d labels, cartons sealed, and the right handling equipment used.","","Confirm each box only after you have actually checked it.");
  add("Container / vehicle inspection points","doors inspected|floor inspected|locking system inspected|no holes or cracks|no odor contamination|holes|cracks|roof|walls|interior|exterior|cleanliness|clean|dry|odour|inspection point|tyre|brake|light|horn|wiper|mirror|first aid kit|fire extinguisher|safety equipment|condition ok|fit for use|fit for loading|ventilation|cargo worthy","Before loading, a container or vehicle is checked: doors and locks work, the floor is sound, there are no holes or cracks (light test), it is clean, dry and free of smell. Defects mean the unit must be rejected or repaired.","","");
  add("Fumigation process details","gas introduction pipes|gas introduction|concentration readings|concentration monitored|exposure period|fumigant|dosage|dose|aeration|gas free|ventilated|covered|sheet|tarpaulin|fumigator|applied by|chemical used|chemical|application|exposure|temperature during fumigation|humidity recorded","Fumigation kills pests by filling a sealed space with gas for a set exposure period at a set dose and temperature. The record includes the chemical, dose, exposure hours, concentration readings and aeration (clearing the gas) before cargo can be handled.","","");
  add("Records, archive & closure","archived|archive reference|archived by|records archived|records maintained|audit records|audit trail|record retention|retention period|record closed|closed|closure|case closed|documentation closed|process closed|transaction closed|shipment file|file reviewed|file closed|all documents filed|all documents scanned|all documents matched|documents scanned|erp updated|ledger updated|accounting system|erp ledger|final reconciliation|reconciliation|finalize|complete shipment record|export documents archived|record|document control|control number|control no","At the end of a job every document is filed, matched and scanned, the ERP/ledger is updated, and the file is closed and archived for the legal retention period (for audit and Customs). The archive reference lets anyone find the file later.","","Customs and tax authorities can ask for old records, so keeping them complete matters.");
  add("Charges & billing","loading charge|loading charges|labour charge|labor charge|documentation charges|port and documentation charges|bank charges|opening charges|reimbursement charges|charge type|charges|charge break up|charge tiers|billing cycle|billing reference|billing information|outstanding charges|charge logged|other charges|additional services|who pays charges|payment instructions|payment type|payment released|bank details collected|handling fee|service charge|fee","The costs charged for each service in the shipment (loading, documentation, bank, handling). Each charge has a type, an amount and a payer, and appears on the bill with a billing reference.","","");
  add("Interest / Fine / Penalty / Late fee","interest|fine|penalty|late delivery penalty|late fee|liquidated damages|compensation|additional duties|surcharge penalty","Money added for late payment, late delivery or a breach of rules. Interest is charged per period on overdue amounts; penalties and fines are fixed by contract or by law.","","");
  add("Quality defects & NCR","defect|defects|defects noted|critical defects|major defects|minor defects|physical defects|defect details|ncr|ncr details|ncr severity|non conformance|nonconformance|corrective action|preventive action|deviation|deviations identified|investigation|findings|root cause|oos|out of specification|qc report|quality report|quality check|rejection|query details|dimensional check|weight within tolerance|tolerance|agreed tolerance|weight reconciliation|actual weight|estimated weight|approximate weight|originally declared weight|weight measured","In quality control, defects are graded critical, major or minor against the agreed standard. A Non-Conformance Report (NCR) records what went wrong, its severity, the root cause and the corrective action. Weights are compared with the declared weight within an agreed tolerance (%).","","");
  add("Endorsement, dishonour & protest","endorsement|endorsed|endorse|endorsement wording|holder|new holder|ownership of the bill|dishonour|dishonor|holder informed of dishonour|notice given to all endorsers|endorsers|protest|protest prepared|negotiability|negotiable|non negotiable|to order","Negotiable documents such as a Bill of Lading or Bill of Exchange can be endorsed (signed over) to a new holder. If a bill is not paid when due it is dishonoured, the holder must notify earlier endorsers, and a notary may prepare a protest as legal proof.","","");
  add("Authority, accreditation & legal clauses","aeo|aeo certificate|authorised economic operator|accreditation|accreditation no|laboratory accreditation|inspector accreditation|competent authority|jurisdiction|governing law|court|arbitration|liability clause|liability marking|disclaimer|exclusions|explicitly excluded|not authorized|functions authorized|sanctions|no sanctions|kyc|kyc verification|id proof|identification presented|cites|cites appendix|wildlife|captive bred|legally acquired|lawfully sourced|legal restrictions|regulatory requirements|rvc|regional value content|general rules for interpretation|gri|hs classification","Legal and compliance details: certificates that prove an operator is trusted (AEO), accreditation numbers of labs and inspectors, the court or law that governs a contract, sanctions and KYC checks, CITES permits for wildlife products, and the General Rules for Interpretation (GRI) used to classify goods under the HS.","","");
  add("Priority, urgency & delivery method","priority|priority level|urgency|urgent|delivery priority|delivery method|delivery exception|exception type|exception report|escalation|escalated|referred to|communication channel|channel|courier|courier service|distribution list|recipient|recipient company|certificate sent to|parties notified|pre arrival notification|notified|notification|inquiry id|enquiry","How urgent the shipment or request is and how it will be delivered or reported: standard vs express, courier or e-mail, who must be informed, and how an exception (delay, damage, shortage) is escalated.","","");
  add("Branch / agent / booking source","branch|branch office|agent branch|booking branch|agent code|booked by|office of issue|agency|agency accreditation|issuing office|handled by|booking type|booking finalized|handed over|documentation team|internal job file|job file|job number|job no|job id","The office or agent that handles a booking and the internal job file (job number) created for the shipment so every team can find it. A booking is \u201cfinalised\u201d when it is confirmed and handed to the documentation team.","","");
  add("Certificate (number, type, issuer)","certificate no|certificate number|certificate type|certificate details|certificate prepared|certificate sent|any special certificates|weight certificate|issuing authority|issuing agency|issued by authority|authorization type|authorisation type|registration type|business registration|business type|gst certificate|gst applicability|cargo registration|registration no|license|licence|permit","The identifiers and kind of certificate or registration: its number, who issued it and what it certifies. Use the number printed on the real certificate.","","");
  add("System-generated / computed fields","system generated|computed|checksum|hash|check digit|verification code|qr code|qr reference|verification id|barcode|page numbering|key to abbreviations|summary|overall verdict|documents checklist|mileage since|calculation method|calculated|auto generated|auto filled","Some boxes are filled automatically by the system (a number, check digit, QR/verification code, totals or a verdict). You cannot type them; they change when the values they depend on change.","","");
  add("Cargo category / type / sensitivity","cargo category|cargo type|cargo load type|cargo sensitivity|nature of cargo|nature of contract|shipment type|special cargo|special cargo flag|special cargo requirements|out of gauge|oversized|oog|lithium batteries|live animals|marine pollutant|perishable|hazardous cargo|temperature sensitive|high value|valuable|general cargo|project cargo|bulk|break bulk|liquid|dry bulk","The class of cargo decides how it is booked and handled: general, perishable, hazardous, high-value, project or out-of-gauge (too big for a normal container). Special cargo (lithium batteries, live animals, marine pollutants) needs extra approval and declarations.","","");
  add("Export scheme / authorisation","export scheme|exporting under a scheme|scheme|scheme type|advance authorisation|epcg|dfia|export obligation|exclusive|authorization type|notification|exemption","Whether the shipment is made under a government scheme such as Advance Authorisation, DFIA or EPCG, which gives duty benefits in return for an export obligation. If not, choose None.","","");
  add("Intended use / end use","intended use|intended end use|end use|purpose of import|purpose|use|end user|purpose of shipment|fit for human consumption|human consumption|industrial use|resale|personal use","What the goods will be used for after import (own production, resale, human consumption\u2026). Customs duty and licensing can depend on the end use.","","");
  add("Gross / net / dimensions of a package","height cm|length cm|width cm|height|length|width|depth|payload|maximum payload|capacity|dimension|size|volume","Physical measurements of a package, container or truck \u2014 length \u00d7 width \u00d7 height in centimetres (or metres) and the maximum weight (payload) it can carry.","","");
  add("Evidence, photos & GPS","photographs|photos|photographs taken|photos timestamped|photos gps tagged|gps|gps latitude|gps longitude|gps activated|gps monitoring|latitude|longitude|supporting evidence|evidence attached|evidence type|supporting documents|attached documents|attachments|proof|witness|chain of custody|timestamp","Photos, GPS location and timestamps are evidence of what happened and where (loading, damage, delivery). \u201cChain of custody\u201d means the cargo\u2019s handover from one person to the next is recorded so nothing can be disputed.","","");
  add("Declared conveyance / point of entry","declared means of conveyance|declared point of entry|designated point of entry|means of conveyance|point of entry|entry point|mode of conveyance|last port called|next port|port of call|berth|jetty|berth no|ground handling|ground handler|yard entry|exit security|security check|cleared for yard","Details used by plant-quarantine and port authorities: the vessel/flight that carries the goods, the official point of entry into the destination country, the berth/jetty and last/next ports of call, and the security checks at the yard gate.","","");
  add("Table / list of items","item details|items requested|items treated|item count|count type|credited items|debited items|alternative item|price list|major head|minor head|accounting code|account code|ledger|general ledger|gl code|cost code","Lists of the items or accounting heads the document applies to \u2014 for example the items on a credit/debit note, an item count, or the ledger (major/minor head) a charge is posted to.","","");

  /* =====================================================================
     MATCHING + EXPLAINERS
     ===================================================================== */
  const GENERIC_TITLES = new Set(["Date / Time","Place of Issue","Address","Contact Person / Phone / Email","Name of Company","Remarks / Notes","Status / Verified / Confirmed / Checked","Signature / Stamp / Seal","Prepared / Checked / Approved By","Copies / Original / Duplicate","Revision / Version / Amendment","Invoice Number / Reference Number","Currency","Invoice Value / Amount","Description of Goods"]);

  /* best glossary entries for a label / field name (longest, most specific alias first) */
  function matchGlossary(text, max){
    const tokens = norm(text); if(!tokens.length) return [];
    const scored = [];
    for(const g of GLOSSARY){
      let best = 0;
      for(const seq of g.kt){
        if(!seq.length) continue;
        if(seq.length === 1 && seq[0].length < 3 && tokens.length > 1) continue;   // "do", "an", "so" would match everything
        if(!hasSeq(tokens, seq)) continue;
        let sc = seq.length * 10 + (seq.length === tokens.length ? 25 : 0);
        if(GENERIC_TITLES.has(g.t)) sc -= 6;
        if(sc > best) best = sc;
      }
      if(best > 0) scored.push({g, sc: best});
    }
    scored.sort((a, b) => b.sc - a.sc);
    return scored.slice(0, max || 3).map(x => { x.g._sc = x.sc; return x.g; });
  }

  function exampleFromMsg(msg){
    const m = /e\.?g\.?,?\s*([^.;()]+?)(?:[.;)]|$)/i.exec(String(msg || ""));
    return m ? m[1].trim() : "";
  }
  function exampleFor(def){
    if(!def) return "";
    if(def.learn && def.learn.example && String(def.learn.example).length < 90) return stripTags(def.learn.example);
    const fromMsg = exampleFromMsg(def.patternMsg || def.errorMsg || def.requiredMsg);
    if(fromMsg) return fromMsg;
    if(def.placeholder && String(def.placeholder).length < 80) return stripTags(def.placeholder);
    const g = matchGlossary(stripTags(def.label || "") || (def.name || ""), 1)[0];
    return g && g.x ? g.x : "";
  }

  /* format-only repairs: only ever returns a value that really satisfies the field's own pattern */
  function suggestFix(value, def){
    try{
      if(!def || !def.pattern) return "";
      const re = new RegExp(def.pattern); const v = String(value == null ? "" : value);
      if(re.test(v.trim())) return "";
      const t = v.trim();
      const cands = [
        t.toUpperCase(), t.replace(/\s+/g, ""), t.toUpperCase().replace(/\s+/g, ""), t.replace(/[\s\-_.\/]+/g, ""), t.toUpperCase().replace(/[\s\-_.\/]+/g, ""),
        t.replace(/[^0-9]/g, ""), t.toUpperCase().replace(/[^A-Z0-9]/g, ""), t.replace(/\s+/g, " "), t.replace(/,/g, ""), t.replace(/[^0-9.]/g, ""), t.toLowerCase()
      ];
      for(const c of cands){ if(c && c !== v && re.test(c)) return c; }
    }catch(e){}
    return "";
  }

  /* ---------- explain one form field ---------- */
  function explainField(def, ctx){
    ctx = ctx || {};
    const label = stripTags(def.label || def.name || "this field");
    const learn = def.learn || null;
    let gm = matchGlossary(label, 3);
    if(!gm.length && def.name) gm = matchGlossary(def.name, 2);
    const specific = gm.filter(g => !GENERIC_TITLES.has(g.t));
    const terms = (specific.length ? specific : gm).slice(0, 2);
    const help = def.help ? stripTags(def.help) : "";
    const sections = [];
    let source = "generic";

    if(learn && learn.explanation){ sections.push({k:"what", h:"What is it?", t:stripTags(learn.explanation)}); source = "learn"; }
    else if(terms.length){ sections.push({k:"what", h:"What is it?", t:terms[0].d}); source = "glossary"; }
    else if(help){ sections.push({k:"what", h:"What is it?", t:help}); source = "help"; }
    else {
      const stepTitle = ctx.step && ctx.step.title ? ctx.step.title : "";
      const docTitle = ctx.cfg && ctx.cfg.title ? ctx.cfg.title : "this document";
      sections.push({k:"what", h:"What is it?", t:"\u201c" + label + "\u201d is a detail asked for in the " + (stepTitle ? "\u201c" + stepTitle + "\u201d section of the " : "") + docTitle + ". Fill it with the value that belongs to THIS shipment \u2014 copy it from the Create a Job form or the documents you already completed whenever it appears there."});
    }
    if(help && source !== "help") sections.push({k:"help", h:"About this box", t:help});
    if(learn && learn.purpose) sections.push({k:"why", h:"Why it matters", t:stripTags(learn.purpose)});
    else if(terms[0] && terms[0].w) sections.push({k:"why", h:"Why it matters", t:terms[0].w});
    if(learn && learn.context) sections.push({k:"where", h:"Where & when it is used", t:stripTags(learn.context)});
    const fmt = [];
    if(def.patternMsg) fmt.push(stripTags(def.patternMsg));
    if(learn && learn.validation) fmt.push(stripTags(learn.validation));
    if(fmt.length) sections.push({k:"format", h:"Format", t:fmt.join(" ")});
    const ex = exampleFor(def);
    if(ex) sections.push({k:"example", h:"Example", t:ex});
    if(learn && learn.mistakes) sections.push({k:"mistakes", h:"Common mistakes", t:stripTags(learn.mistakes)});
    if(learn && learn.hint) sections.push({k:"hint", h:"Tip", t:stripTags(learn.hint)});
    if(source !== "glossary" && terms[0] && !(learn && learn.explanation && terms[0].d === learn.explanation)) sections.push({k:"term", h:"In short: " + terms[0].t, t:terms[0].d});
    if(terms[1] && (terms[1]._sc || 0) >= 20 && terms[1].t !== terms[0].t) sections.push({k:"term", h:"Also: " + terms[1].t, t:terms[1].d});
    sections.push({k:"req", h:def.required ? "Required" : "Optional", t:def.required ? "This document cannot be completed without it." : "You can leave it empty if it does not apply to this shipment."});
    return {title: label, source, sections, terms: terms.map(t => t.t), specific: source !== "generic"};
  }

  /* ---------- explain a document ---------- */
  function explainDoc(cfg){
    if(!cfg) return null;
    return {
      title: cfg.title || "This document",
      subtitle: stripTags(cfg.subtitle || ""),
      module: stripTags(cfg.moduleLabel || ""),
      what: stripTags(cfg.heroDesc || ""),
      objectives: (cfg.objectives || []).map(stripTags)
    };
  }

  /* ---------- search (the "Ask Lyra" box) ---------- */
  const STOP = new Set(["what","is","are","a","an","the","of","in","for","to","meaning","mean","means","define","definition","explain","tell","me","about","how","do","i","why","does","it","this","that","form","full","please","lyra","who","which"]);
  function queryTokens(q){ return norm(q).filter(t => !STOP.has(t)); }
  function search(query){
    const q = queryTokens(query); const out = {glossary: [], docs: [], fields: [], query: String(query || "").trim()};
    if(!q.length) return out;
    const prefix = (t, hay) => t.length >= 3 && hay.some(h => h.indexOf(t) === 0);
    GLOSSARY.forEach(g => {
      let sc = 0;
      for(const seq of g.kt){ if(seq.length === q.length && seq.every((t, i) => t === q[i])){ sc = 100; break; } }
      if(!sc && q.every(t => g.tk.includes(t))) sc = 80;
      if(!sc && g.kt.some(seq => q.every(t => seq.includes(t)))) sc = 60;
      if(!sc){ const hay = g.tk.concat(...g.kt); if(q.every(t => hay.includes(t) || prefix(t, hay))) sc = 40; }
      if(!sc){ const dt = norm(g.d); if(q.every(t => dt.includes(t))) sc = 20; }
      if(sc) out.glossary.push({g, sc});
    });
    out.glossary.sort((a, b) => b.sc - a.sc); out.glossary = out.glossary.slice(0, 6).map(x => x.g);
    try{
      const DC = typeof DOCUMENT_CONFIGS !== "undefined" ? DOCUMENT_CONFIGS : null;
      if(DC){
        const docs = []; const seenLabels = new Set(); const fields = [];
        Object.keys(DC).forEach(slug => {
          const c = DC[slug]; const tt = norm(c.title || ""); let sc = 0;
          if(q.every(t => tt.includes(t) || prefix(t, tt))) sc = 70; else if(q.length > 1 && norm(c.heroDesc || "").length && q.every(t => norm(stripTags(c.heroDesc)).includes(t))) sc = 15;
          if(sc) docs.push({slug, c, sc});
          (c.steps || []).forEach((st, si) => (st.fields || []).forEach(f => {
            if(!f.label) return; const lt = norm(stripTags(f.label));
            if(q.every(t => lt.includes(t) || prefix(t, lt)) && fields.length < 60){ const key = lt.join(" "); const ex = fields.find(x => x.key === key); if(ex){ if(ex.docs.length < 3 && !ex.docs.includes(c.title)) ex.docs.push(c.title); } else if(!seenLabels.has(key)){ seenLabels.add(key); fields.push({key, label: stripTags(f.label), docs: [c.title], def: f, cfg: c, step: st}); } }
          }));
        });
        docs.sort((a, b) => b.sc - a.sc); out.docs = docs.slice(0, 3);
        out.fields = fields.slice(0, 5);
      }
    }catch(e){}
    return out;
  }

  /* quick self-description used by tests / the panel footer */
  const stats = () => ({terms: GLOSSARY.length});

  window.LyraKnowledge = {GLOSSARY, norm, stripTags, matchGlossary, explainField, explainDoc, search, suggestFix, exampleFor, exampleFromMsg, stats};
})();
